#[derive(Debug)]
pub(crate) struct FormatSummary {
    pub(crate) autos: Vec<usize>,
    pub(crate) indices: Vec<usize>,
    pub(crate) keywords: Vec<Name>,
    pub(crate) has_nested_parts: bool,
}

impl TryFrom<&str> for FormatSummary {
    type Error = FormatParseError;

    fn try_from(literal: &str) -> Result<Self, Self::Error> {
        let format_string = FormatString::from_str(literal)?;

        let mut autos = Vec::new();
        let mut indices = Vec::new();
        let mut keywords = Vec::new();
        let mut has_nested_parts = false;

        for format_part in &format_string.format_parts {
            let FormatPart::Field {
                field_name,
                format_spec,
                ..
            } = format_part
            else {
                continue;
            };
            let parsed = FieldName::parse(field_name)?;
            match parsed.field_type {
                FieldType::Auto => autos.push(autos.len()),
                FieldType::Index(i) => indices.push(i),
                FieldType::Keyword(k) => keywords.push(Name::from(k)),
            };

            let nested = FormatString::from_str(format_spec)?;
            for nested_part in nested.format_parts {
                let FormatPart::Field { field_name, .. } = nested_part else {
                    continue;
                };
                let parsed = FieldName::parse(&field_name)?;
                match parsed.field_type {
                    FieldType::Auto => autos.push(autos.len()),
                    FieldType::Index(i) => indices.push(i),
                    FieldType::Keyword(k) => keywords.push(Name::from(k)),
                };
                has_nested_parts = true;
            }
        }

        Ok(FormatSummary {
            autos,
            indices,
            keywords,
            has_nested_parts,
        })
    }
}

impl FormatSummary {
    /// Generate a [`Edit`] to remove unused positional arguments from a `format` call.
    pub(crate) fn remove_unused_positional_arguments_from_format_call(
        &self,
        unused_arguments: &[usize],
        call: &ast::ExprCall,
        locator: &Locator,
        stylist: &Stylist,
    ) -> anyhow::Result<Edit> {
        let argument_count = call.arguments.args.len() + call.arguments.keywords.len();
        let unused: Vec<usize> = unused_arguments
            .iter()
            .copied()
            .filter(|index| {
                *index < argument_count
                    && !self.autos.contains(index)
                    && !self.indices.contains(index)
            })
            .collect();

        let source_range = TextRange::new(
            call.range().start().min(call.func.start()),
            call.range().end().max(call.func.end()),
        );
        let source_code = &locator.contents()[source_range];
        let wrapped = format!("({source_code})");
        let mut expression = match_expression(&wrapped)?;
        {
            let call_expr = match_call_mut(&mut expression)?;
            let mut index = 0;
            call_expr.args.retain(|_| {
                let is_unused = unused.contains(&index);
                index += 1;
                !is_unused
            });
        }

        let mut state = CodegenState {
            default_newline: stylist.line_ending().as_str(),
            default_indent: stylist.indentation().as_str(),
            ..Default::default()
        };
        expression.codegen(&mut state);
        let mut output = state.to_string();
        output.drain(0..1);
        output.drain(output.len() - 1..output.len());
        Ok(Edit::range_replacement(output, call.range()))
    }
}

